import{_ as a,o,c as s,a0 as r}from"./chunks/framework.CNDWyMYS.js";const h=JSON.parse('{"title":"luarocks new_version","description":"","frontmatter":{},"headers":[],"relativePath":"luarocks_new_version.md","filePath":"luarocks_new_version.md"}'),t={name:"luarocks_new_version.md"};function c(n,e,i,l,p,d){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="luarocks-new-version" tabindex="-1">luarocks new_version <a class="header-anchor" href="#luarocks-new-version" aria-label="Permalink to &quot;luarocks new_version&quot;">​</a></h1><p>Auto-write a rockspec for a new version of a rock.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p><code>luarocks new_version [--tag=&lt;tag&gt;] [&lt;package&gt;|&lt;rockspec&gt;] [&lt;new_version&gt;] [&lt;new_url&gt;]</code></p><p>Creates a rockspec for a new version of a rock based on data from an existing rockspec.</p><p>If a package name is given, it downloads the latest rockspec from the public rocks server. If a rockspec URL or path is given, it uses it instead. If no argument is given, it looks for a rockspec same way the <a href="./luarocks_make.html">luarocks make</a> command does.</p><p>New version of the rockspec can be specified by passing it as the second argument or by using <code>--tag</code> option: the tag will be used as version, with leading &quot;v&quot; removed.</p><p>New URL (value of <code>source.url</code> rockspec field) can be passed as the third argument. If it&#39;s not passed explicitly it will be inferred from the old URL by replacing occurrences of the old version in it with the new one. If new tag (value of <code>source.tag</code>) is not set explicitly using <code>--tag</code>, it is updated in the same way.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>Creating a rockspec for version <code>0.2.0</code> from an scm rockspec in current directory, with new tag <code>v0.2.0</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>luarocks new_version --tag=v0.2.0</span></span></code></pre></div><p>This creates a rockspec called <code>my-rock-0.2.0-1.rockspec</code> in current directory.</p>',12)])])}const k=a(t,[["render",c]]);export{h as __pageData,k as default};
